    if not location or location.strip() == "":
        default_location = os.environ.get('DEFAULT_WEATHER_LOCATION')
        if not default_location:
            return "Error: Location parameter cannot be empty and DEFAULT_WEATHER_LOCATION not set."
        location = default_location

    base_url = "http://api.weatherapi.com/v1/current.json"
    params = {
        "key": api_key,
        "q": location
    }

    try:
        response = requests.get(base_url, params=params)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        data = response.json()

        if 'error' in data:
            return f"Error: {data['error']['message']}"

        current = data['current']
        condition = current['condition']['text']
        temperature_c = current['temp_c']
        humidity = current['humidity']

        return f"The weather in {location} is {condition} with a temperature of {temperature_c}°C and humidity of {humidity}%."

    except requests.exceptions.RequestException as e:
        return f"Error: Could not retrieve weather information for {location}. {e}"
    except Exception as e:
        return f"An unexpected error occurred: {e}"

